        move.l  DTCN3,%d0
        move.l  #SLOT,%d1
        divu.l  %d1,%d0                 | the 50 ms slot since the loop began
        move.l  #NSLOTS,%d1
        cmp.l   %d1,%d0
        bcc     bb_9                    | past the animation: black
        lea     BS_SLOTS,%a0
        mvz.b   (%a0,%d0.l),%d0
        move.l  #255,%d1
        cmp.l   %d1,%d0
        beq     bb_9                    | a black slot
        lsl.l   #8,%d0
        lsl.l   #2,%d0                  | 1,024 bytes a frame
        lea     BS_FRAMES,%a0
        add.l   %d0,%a0
        move.l  8(%sp),%a1
        move.l  12(%a1),%a1             | the surface's bits: the LCD plane
        move.l  #256,%d1
bb_1:   move.l  (%a0)+,(%a1)+
